"use strict";

// imports/common/node-base.ts
function execNode(handlerFunction, errorOutcome) {
  try {
    handlerFunction();
  } catch (e) {
    logger.error("Exception: " + e);
    logger.debug("Stack trace " + e.stack);
    action.goTo(errorOutcome);
  }
}

// imports/common/http.ts
function getHttpHeader(headerName) {
  var headerValues = requestHeaders.get(headerName);
  return headerValues ? String(headerValues.get(0)) : null;
}
function getUrlParameter(parameterName) {
  var parameterValues = requestParameters.get(parameterName);
  return parameterValues ? String(parameterValues.get(0)) : null;
}
function basicAuthHeader(user, password) {
  return "Basic ".concat(utils.base64.encode("".concat(user, ":").concat(password)));
}

// imports/oauth2/introspect.ts
function introspectAccessToken(introspectEndpoint, httpRetries, accessToken, clientId, clientSecret, clientProfile, clientAuthMethod) {
  var requestBody = "token=".concat(encodeURIComponent(accessToken));
  var headers = {
    "content-type": "application/x-www-form-urlencoded"
  };
  switch (clientAuthMethod) {
    case "SECRET_POST":
      requestBody = "".concat(requestBody, "&client_id=").concat(encodeURIComponent(clientId), "&client_secret=").concat(encodeURIComponent(clientSecret));
      break;
    case "SECRET_BASIC":
      headers["authorization"] = basicAuthHeader(clientId, clientSecret);
      break;
    default:
      logger.error("unknown auth method " + clientAuthMethod);
      return null;
  }
  logger.debug("Calling introspect endpoint " + introspectEndpoint);
  logger.debug("Request body " + JSON.stringify(requestBody));
  var response = null;
  for (var attempt = 0; attempt < httpRetries; attempt++) {
    logger.debug("Attempt " + (attempt + 1) + " of " + httpRetries);
    try {
      var options = {
        method: "POST",
        body: requestBody,
        headers: headers
      };
      if (clientProfile && clientProfile !== "") {
        options.clientName = clientProfile;
      }
      logger.debug("Request: " + JSON.stringify(options));
      response = httpClient.send(introspectEndpoint, options).get();
      if (response) {
        logger.debug("Got response");
        break;
      }
    } catch (e) {
      logger.error("Exception calling introspect endpoint " + e);
    }
  }
  if (!response) {
    logger.error("Bad response");
    return null;
  }
  var status = response.status;
  logger.debug("Status " + status + " Response " + JSON.stringify(response.text()));
  if (response.ok) {
    return response.json();
  }
  logger.error("Bad status");
  return null;
}

// imports/common/state.ts
function putStatePath(path, value) {
  var transient = arguments.length > 2 && arguments[2] !== undefined ? arguments[2] : false;
  var keys = path.split(".");
  var rootKey = keys[0];
  var newValue = null;
  if (keys.length === 1) {
    newValue = value;
  } else {
    var existing = nodeState.get(rootKey) || {};
    newValue = existing;
    for (var i = 1; i < keys.length - 1; i++) {
      var key = keys[i];
      newValue[key] = newValue[key] || {};
      newValue = newValue[key];
    }
    newValue[keys[keys.length - 1]] = value;
  }
  if (transient) {
    nodeState.putTransient(rootKey, newValue);
  } else {
    nodeState.putShared(rootKey, newValue);
  }
}

// packages/oauth2-introspect/src/oauth2-introspect.ts
var nodeOutcomes = {
  VALID: "Valid Token",
  INVALID: "Invalid Token",
  NO_TOKEN: "No Token",
  FAILED_CLAIMS: "Failed Claims",
  UNLISTED_CLIENT: "Unlisted Client",
  ERROR: "Error"
};
var BEARER_TYPE = {
  AUTHZ_HEADER: "AUTHZ_HEADER",
  CUSTOM_HEADER: "CUSTOM_HEADER",
  CALLBACK: "CALLBACK",
  STATE: "STATE",
  URL_PARAMETER: "URL_PARAMETER"
};
var REQUEST_RETRIES = 3;
var SHARED_STATE_RESULT = "tokenIntrospectResult";
function getToken(bearerType) {
  var token = null;
  switch (bearerType) {
    case BEARER_TYPE.AUTHZ_HEADER:
      logger.debug("Getting bearer token from authz header");
      token = getHttpHeader("authorization");
      break;
    case BEARER_TYPE.CUSTOM_HEADER:
      logger.debug("Getting bearer token from header ".concat(properties.bearerIdentifier));
      token = getHttpHeader(properties.bearerIdentifier);
      break;
    case BEARER_TYPE.STATE:
      logger.debug("Getting token from state variable ".concat(properties.bearerIdentifier));
      token = nodeState.get(properties.bearerIdentifier);
      break;
    case BEARER_TYPE.URL_PARAMETER:
      logger.debug("Getting token url parameter ".concat(properties.bearerIdentifier));
      token = getUrlParameter(properties.bearerIdentifier);
      break;
    default:
      logger.error("Unsupported bearer type: \"".concat(bearerType, "\""));
      return null;
  }
  return token ? token.trim().replace(/^bearer\s+/i, "") : null;
}
execNode(function () {
  var token = null;
  if (properties.bearerType === BEARER_TYPE.CALLBACK) {
    if (callbacks.isEmpty()) {
      callbacksBuilder.stringAttributeInputCallback("token", "Token", "", true);
      return;
    }
    token = callbacks.getStringAttributeInputCallbacks().get(0);
  } else {
    token = getToken(properties.bearerType);
  }
  if (!token) {
    logger.error("No token found");
    action.goTo(nodeOutcomes.NO_TOKEN);
    return;
  }
  var introspectEndpoint = properties.introspectEndpoint;
  if (!introspectEndpoint) {
    logger.error("No introspect endpoint configured");
    action.goTo(nodeOutcomes.ERROR);
    return;
  }
  logger.debug("Sending token introspect request to endpoint " + introspectEndpoint);
  var introspectResult = introspectAccessToken(introspectEndpoint, REQUEST_RETRIES, token, properties.clientId, properties.clientSecret, properties.clientProfile, properties.clientAuthenticationMethod);
  if (!introspectResult) {
    logger.error("Bad introspect result");
    action.goTo(nodeOutcomes.ERROR);
    return;
  }
  if (!introspectResult.active) {
    logger.error("Invalid access token");
    action.goTo(nodeOutcomes.INVALID);
    return;
  }
  if (properties.requiredClaims) {
    var failed = false;
    Object.keys(properties.requiredClaims).forEach(function (requiredClaim) {
      var requiredValue = properties.requiredClaims[requiredClaim];
      var value = introspectResult[requiredClaim];
      if (typeof value === "undefined") {
        logger.debug("Claim ".concat(requiredClaim, " not found in introspect results"));
        failed = true;
        return;
      }
      if (value !== requiredValue) {
        logger.debug("Value for ".concat(requiredClaim, " (").concat(value, ") does not match required value (").concat(requiredValue, ")"));
        failed = true;
        return;
      }
    });
    if (failed) {
      action.goTo(nodeOutcomes.FAILED_CLAIMS);
      return;
    }
  }
  if (properties.allowedClients && properties.allowedClients.length > 0) {
    var clientId = introspectResult.client_id;
    logger.debug("Checking client id ".concat(clientId));
    if (!clientId) {
      logger.error("No client_id in introspect results");
      action.goTo(nodeOutcomes.UNLISTED_CLIENT);
      return;
    }
    var clientFound = false;
    properties.allowedClients.forEach(function (allowedClient) {
      logger.debug("Checking against allowed client ".concat(allowedClient));
      if (clientId === allowedClient) {
        logger.debug("Matched client");
        clientFound = true;
      }
    });
    if (!clientFound) {
      logger.error("Client not found in allowlist");
      action.goTo(nodeOutcomes.UNLISTED_CLIENT);
      return;
    }
  }
  if (properties.saveResults) {
    logger.debug("Saving to state");
    nodeState.putShared(SHARED_STATE_RESULT, introspectResult);
  }
  if (properties.mapAttributesToState) {
    Object.keys(properties.mapAttributesToState).forEach(function (statePath) {
      var claim = properties.mapAttributesToState[statePath];
      var value = introspectResult[claim];
      putStatePath(statePath, value);
    });
  }
  action.goTo(nodeOutcomes.VALID);
}, nodeOutcomes.ERROR);
